answer_code:
function intersection(a, b) {
  const inB = new Set(b);
  const seen = new Set();
  const result = [];
  for (const value of a) {
    if (inB.has(value) && !seen.has(value)) {
      seen.add(value);
      result.push(value);
    }
  }
  return result;
}

